1	//===-- String Length -------------------------------------------*- C++ -*-===//
2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	//
9	// Basic implementation and dispatch mechanism for performance-sensitive string-
10	// related code.
11	//
12	//===----------------------------------------------------------------------===//
13	
14	#ifndef LLVM_LIBC_SRC_STRING_STRING_LENGTH_H
15	#define LLVM_LIBC_SRC_STRING_STRING_LENGTH_H
16	
17	#include "hdr/limits_macros.h"
18	#include "hdr/stdint_proxy.h" // uintptr_t
19	#include "hdr/types/size_t.h"
20	#include "src/__support/CPP/type_traits.h" // cpp::is_same_v
21	
22	#if LIBC_HAS_VECTOR_TYPE
23	#include "src/string/memory_utils/generic/inline_strlen.h"
24	#endif
25	#if defined(LIBC_TARGET_ARCH_IS_X86)
26	#include "src/string/memory_utils/x86_64/inline_strlen.h"
27	#elif defined(LIBC_TARGET_ARCH_IS_AARCH64) &&                                  \
28	    (defined(LIBC_TARGET_CPU_HAS_SVE) || defined(__ARM_NEON))
29	#include "src/string/memory_utils/aarch64/inline_strlen.h"
30	#endif
31	
32	// Set sensible defaults
33	#ifndef LIBC_COPT_STRING_LENGTH_IMPL
34	#define LIBC_COPT_STRING_LENGTH_IMPL element
35	#endif
36	#ifndef LIBC_COPT_FIND_FIRST_CHARACTER_IMPL
37	#define LIBC_COPT_FIND_FIRST_CHARACTER_IMPL element
38	#endif
39	
40	namespace LIBC_NAMESPACE_DECL {
41	namespace internal {
42	
43	#if !LIBC_HAS_VECTOR_TYPE
44	// Forward any clang vector impls to architecture specific ones
45	namespace arch_vector {}
46	namespace clang_vector = arch_vector;
47	#endif
48	
49	namespace element {
50	// Element-by-element (usually a byte, but wider for wchar) implementations of
51	// functions that search for data.  Slow, but easy to understand and analyze.
52	
53	// Returns the length of a string, denoted by the first occurrence
54	// of a null terminator.
55	LIBC_INLINE size_t string_length(const char *src) {
56	  size_t length;
57	  for (length = 0; *src; ++src, ++length)
58	    ;
59	  return length;
60	}
61	
62	template <typename T> LIBC_INLINE size_t string_length_element(const T *src) {
63	  size_t length;
64	  for (length = 0; *src; ++src, ++length)
65	    ;
66	  return length;
67	}
68	
69	LIBC_INLINE void *find_first_character(const unsigned char *src,
70	                                       unsigned char ch, size_t n) {
71	  for (; n && *src != ch; --n, ++src)
72	    ;
73	  return n ? const_cast<unsigned char *>(src) : nullptr;
74	}
75	} // namespace element
76	
77	namespace word {
78	// Non-vector, implementations of functions that search for data by reading from
79	// memory word-by-word.
80	
81	template <typename Word> LIBC_INLINE constexpr Word repeat_byte(Word byte) {
82	  static_assert(CHAR_BIT == 8, "repeat_byte assumes a byte is 8 bits.");
83	  constexpr size_t BITS_IN_BYTE = CHAR_BIT;
84	  constexpr size_t BYTE_MASK = 0xff;
85	  Word result = 0;
86	  byte = byte & BYTE_MASK;
87	  for (size_t i = 0; i < sizeof(Word); ++i)
88	    result = (result << BITS_IN_BYTE) | byte;
89	  return result;
90	}
91	
92	// The goal of this function is to take in a block of arbitrary size and return
93	// if it has any bytes equal to zero without branching. This is done by
94	// transforming the block such that zero bytes become non-zero and non-zero
95	// bytes become zero.
96	// The first transformation relies on the properties of carrying in arithmetic
97	// subtraction. Specifically, if 0x01 is subtracted from a byte that is 0x00,
98	// then the result for that byte must be equal to 0xff (or 0xfe if the next byte
99	// needs a carry as well).
100	// The next transformation is a simple mask. All zero bytes will have the high
101	// bit set after the subtraction, so each byte is masked with 0x80. This narrows
102	// the set of bytes that result in a non-zero value to only zero bytes and bytes
103	// with the high bit and any other bit set.
104	// The final transformation masks the result of the previous transformations
105	// with the inverse of the original byte. This means that any byte that had the
106	// high bit set will no longer have it set, narrowing the list of bytes which
107	// result in non-zero values to just the zero byte.
108	template <typename Word> LIBC_INLINE constexpr bool has_zeroes(Word block) {
109	  constexpr unsigned int LOW_BITS = repeat_byte<Word>(0x01);
110	  constexpr Word HIGH_BITS = repeat_byte<Word>(0x80);
111	  Word subtracted = block - LOW_BITS;
112	  Word inverted = ~block;
113	  return (subtracted & inverted & HIGH_BITS) != 0;
114	}
115	
116	// Unsigned int is the default size for most processors, and on x86-64 it
117	// performs better than larger sizes when the src pointer can't be assumed to
118	// be aligned to a word boundary, so it's the size we use for reading the
119	// string a block at a time.
120	
121	LIBC_INLINE size_t string_length(const char *src) {
122	  using Word = unsigned int;
123	  const char *char_ptr = src;
124	  // Step 1: read 1 byte at a time to align to block size
125	  for (; reinterpret_cast<uintptr_t>(char_ptr) % sizeof(Word) != 0;
126	       ++char_ptr) {
127	    if (*char_ptr == '\0')
128	      return static_cast<size_t>(char_ptr - src);
129	  }
130	  // Step 2: read blocks
131	  for (const Word *block_ptr = reinterpret_cast<const Word *>(char_ptr);
132	       !has_zeroes<Word>(*block_ptr); ++block_ptr) {
133	    char_ptr = reinterpret_cast<const char *>(block_ptr);
134	  }
135	  // Step 3: find the zero in the block
136	  for (; *char_ptr != '\0'; ++char_ptr) {
137	    ;
138	  }
139	  return static_cast<size_t>(char_ptr - src);
140	}
141	
142	LIBC_NO_SANITIZE_OOB_ACCESS LIBC_INLINE void *
143	find_first_character(const unsigned char *src, unsigned char ch,
144	                     size_t max_strlen = cpp::numeric_limits<size_t>::max()) {
145	  using Word = unsigned int;
146	  const unsigned char *char_ptr = src;
147	  size_t cur = 0;
148	
149	  // If the maximum size of the string is small, the overhead of aligning to a
150	  // word boundary and generating a bitmask of the appropriate size may be
151	  // greater than the gains from reading larger chunks. Based on some testing,
152	  // the crossover point between when it's faster to just read bytewise and read
153	  // blocks is somewhere between 16 and 32, so 4 times the size of the block
154	  // should be in that range.
155	  if (max_strlen < (sizeof(Word) * 4)) {
156	    return element::find_first_character(src, ch, max_strlen);
157	  }
158	  size_t n = max_strlen;
159	  // Step 1: read 1 byte at a time to align to block size
160	  for (; cur < n && reinterpret_cast<uintptr_t>(char_ptr) % sizeof(Word) != 0;
161	       ++cur, ++char_ptr) {
162	    if (*char_ptr == ch)
163	      return const_cast<unsigned char *>(char_ptr);
164	  }
165	
166	  const Word ch_mask = repeat_byte<Word>(ch);
167	
168	  // Step 2: read blocks
169	  const Word *block_ptr = reinterpret_cast<const Word *>(char_ptr);
170	  for (; cur < n && !has_zeroes<Word>((*block_ptr) ^ ch_mask);
171	       cur += sizeof(Word), ++block_ptr)
172	    ;
173	  char_ptr = reinterpret_cast<const unsigned char *>(block_ptr);
174	
175	  // Step 3: find the match in the block
176	  for (; cur < n && *char_ptr != ch; ++cur, ++char_ptr) {
177	    ;
178	  }
179	
180	  if (cur >= n || *char_ptr != ch)
181	    return static_cast<void *>(nullptr);
182	
183	  return const_cast<unsigned char *>(char_ptr);
184	}
185	
186	} // namespace word
187	
188	// Dispatch mechanism for implementations of performance-sensitive
189	// functions. Always measure, but generally from lower- to higher-performance
190	// order:
191	//
192	// 1. element - read char-by-char or wchar-by-wchar
193	// 3. word - read word-by-word
194	// 3. clang_vector - read using clang's internal vector types
195	// 4. arch_vector - hand-coded per architecture. Possibly in asm, or with
196	// intrinsics.
197	//
198	// The called implemenation is chosen at build-time by setting
199	// LIBC_CONF_{FUNC}_IMPL in config.json
200	static constexpr auto &string_length_impl =
201	    LIBC_COPT_STRING_LENGTH_IMPL::string_length;
202	static constexpr auto &find_first_character_impl =
203	    LIBC_COPT_FIND_FIRST_CHARACTER_IMPL::find_first_character;
204	
205	template <typename T> LIBC_INLINE size_t string_length(const T *src) {
206	  if constexpr (cpp::is_same_v<T, char>)
207	    return string_length_impl(src);
208	  return element::string_length_element<T>(src);
209	}
210	
211	} // namespace internal
212	} // namespace LIBC_NAMESPACE_DECL
213	
214	#endif //  LLVM_LIBC_SRC_STRING_STRING_LENGTH_H
